/**
 * Finds the address of the transfer authority.
 * @returns
 */
const pda_findTransferAuthorityAddress = async (name) => {
    return await index_browser_esm.PublicKey.findProgramAddress([
        browser.utils.bytes.utf8.encode(TRANSFER_AUTHORITY_SEED),
        browser.utils.bytes.utf8.encode(name),
    ], constants_TRANSFER_AUTHORITY_ADDRESS);
};
/**
 * Finds the address of the marketplace.
 * @returns
 */
const pda_findMarketplaceAddress = async (name) => {
    return await index_browser_esm.PublicKey.findProgramAddress([browser.utils.bytes.utf8.encode(MARKETPLACE_SEED), browser.utils.bytes.utf8.encode(name)], constants_TRANSFER_AUTHORITY_ADDRESS);
};
/**
 * Finds the address of the listing.
 * @returns
 */
const pda_findListingAddress = async (mintId) => {
    const [tokenManagerId] = await pda_findTokenManagerAddress(mintId);
    return await index_browser_esm.PublicKey.findProgramAddress([browser.utils.bytes.utf8.encode(LISTING_SEED), tokenManagerId.toBytes()], constants_TRANSFER_AUTHORITY_ADDRESS);
};
/**
 * Finds the address of the transfer.
 * @returns
 */
const pda_findTransferAddress = async (mintId) => {
    const [tokenManagerId] = await pda_findTokenManagerAddress(mintId);
    return await index_browser_esm.PublicKey.findProgramAddress([browser.utils.bytes.utf8.encode(TRANSFER_SEED), tokenManagerId.toBytes()], constants_TRANSFER_AUTHORITY_ADDRESS);
};
