const generateWrapSolTx = async (ctx, destination, lamports)=>{
    const { walletPublicKey , connection , commitment , blockhash  } = ctx;
    const destinationAta = associatedTokenAddress(NATIVE_MINT, destination, TOKEN_PROGRAM_ID);
    const [destinationAccount, destinationAtaAccount] = await connection.getMultipleAccountsInfo([
        destination,
        destinationAta
    ], commitment);
    //
    // Require the account to either be a system program account or a brand new
    // account.
    //
    if (destinationAccount && !destinationAccount.owner.equals(SystemProgram.programId)) {
        throw new Error("invalid account");
    }
    const tx = new Transaction();
    if (!destinationAtaAccount) {
        tx.instructions.push(createAssociatedTokenAccountInstruction(walletPublicKey, destinationAta, destination, NATIVE_MINT, TOKEN_PROGRAM_ID));
    }
    tx.instructions.push(SystemProgram.transfer({
        fromPubkey: walletPublicKey,
        toPubkey: new PublicKey(destinationAta),
        lamports
    }));
    tx.instructions.push(createSyncNativeInstruction(new PublicKey(destinationAta)));
    tx.feePayer = walletPublicKey;
    tx.recentBlockhash = blockhash !== null && blockhash !== void 0 ? blockhash : (await connection.getLatestBlockhash(commitment)).blockhash;
    return tx.serialize({
        requireAllSignatures: false
    });
};
