function explorerUrl(base, tx, connectionUrl) {
    switch(base){
        case EthereumExplorer.ETHERSCAN:
            return join(EthereumExplorer.ETHERSCAN, `tx/${tx}`);
        case SolanaExplorer.SOLANA_EXPLORER:
            return join(SolanaExplorer.SOLANA_EXPLORER, `tx/${tx}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLSCAN:
            return join(SolanaExplorer.SOLSCAN, `tx/${tx}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLANA_BEACH:
            return join(SolanaExplorer.SOLANA_BEACH, `transaction/${tx}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLANA_FM:
            return join(SolanaExplorer.SOLANA_FM, `tx/${tx}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.XRAY:
            return join(SolanaExplorer.XRAY, `tx/${tx}${clusterSuffix(base, connectionUrl)}`);
        default:
            throw new Error("unknown explorer base");
    }
}
// returns explorer url to explore addresses
function explorerAddressUrl(base, address, connectionUrl) {
    switch(base){
        case EthereumExplorer.ETHERSCAN:
            return join(EthereumExplorer.ETHERSCAN, `address/${address}`);
        case SolanaExplorer.SOLANA_EXPLORER:
            return join(SolanaExplorer.SOLANA_EXPLORER, `address/${address}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLSCAN:
            return join(SolanaExplorer.SOLSCAN, `account/${address}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLANA_BEACH:
            return join(SolanaExplorer.SOLANA_BEACH, `address/${address}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.SOLANA_FM:
            return join(SolanaExplorer.SOLANA_FM, `address/${address}${clusterSuffix(base, connectionUrl)}`);
        case SolanaExplorer.XRAY:
            return join(SolanaExplorer.XRAY, `account/${address}${clusterSuffix(base, connectionUrl)}`);
        default:
            throw new Error("unknown explorer base");
    }
}
function explorerCompressedNftUrl(address) {
    return `https://xray.helius.xyz/token/${address}`;
}
// Returns the explorer url to display the given nft.
